//! BIP-446 `basics.json` test vectors (from the bitcoin/bips repository), converted to a
//! Rust table. Each entry is `(valid, input_index, spending_tx_hex, comment)`. The spent
//! output embeds the expected template hash in a `<hash> OP_TEMPLATEHASH OP_EQUAL` leaf,
//! recoverable from the spending witness, so `valid` holds iff the template hash computed
//! at `input_index` equals the embedded hash.

pub(crate) const BIP446_BASICS: &[(bool, u32, &str, &str)] = &[
	(true, 0, "",
	"Template hash matches. Input index matches."),
	(false, 1, "",
	"Template hash matches. Input index mismatches."),
	(false, 0, "",
	"Template hash mismatches: incorrect transaction version."),
	(false, 0, "",
	"Template hash mismatches: incorrect transaction locktime."),
	(false, 0, "",
	"Template hash mismatches: incorrect output value."),
	(false, 0, "",
	"Template hash mismatches: incorrect output script."),
	(false, 0, "",
	"Template hash mismatches: incorrect sequence in spending input."),
	(false, 0, "",
	"Template hash mismatches: incorrect sequence in another input."),
	(false, 0, "",
	"Template hash mismatches: spending input contains annex but none was committed."),
	(true, 0, "",
	"Template hash matches with malleated annex for another input."),
	(true, 0, "",
	"Template hash matches with malleated scriptSig for another input."),
	(true, 0, "",
	"Template hash matches with malleated prevout for spending input."),
	(true, 0, "",
	"Template hash matches with malleated prevout for another input."),
	(true, 0, "",
	"Template hash matches with malleated value for corresponding spent output."),
	(true, 0, "",
	"Template hash matches with malleated value for other spent output."),
	(true, 0, "",
	"Template hash matches with malleated scriptpubkey for other spent output."),
	(false, 0, "",
	"Template hash mismatches: spending a script with a different committed hash."),
	(true, 0, "",
	"Template hash matches in the presence of an annex."),
	(false, 0, "",
	"Template hash mismatches: spending with a different annex than that committed."),
];
